VALUES ('Harry’s Diary – Day 40 (Thurs, April 23, 2020)', 'harrys-diary-day-40-thurs-april-23-2020', '<p><img loading="lazy" decoding="async" src="https://media1.tenor.com/images/144035786ff4fc25d47089e067a99826/tenor.gif?itemid=9866186" width="498" height="278" /></p>', 'A tragic day. Nothing I write would be appropriate. I’m going to keep my thoughts to myself and my prayers for the family. Rest in Peace young man. I know you are in a better place.', 'https://changingireland.ie/wp-content/uploads/2020/04/rip-candle-2.jpg', '', '[{"slug":"covid19diaries","title":"Covid-19 Diaries"},{"slug":"harrysdiary","title":"Harry''s Diary"}]', '[{"slug":"changingireland","title":"#ChangingIreland"},{"slug":"communityresponseirl","title":"#CommunityResponseIRL"},{"slug":"covid-19-diary","title":"Covid-19 Diary"}]', '', 249636, 1, '2020-04-23T21:05:11Z', '2020-04-30T16:16:18Z', '2020-04-23T21:05:11Z')
